preConditionHook:
// BREAKOUT CANDLE CLASS SEQUENCE (Brian's notes ON-25, #25). Bar [j] is
// classed against the prior lookback bars (Extremes over bars j + 1 ..
// j + lookback, seeded at j + 1, strict): H (= 1) if it closes above their
// high, L (= -1) if it closes below their low (Brian 2026-11-05: a high
// candle is a close above, symmetric with the low candle), C (= 2) if it trades through either but
// closes back inside, otherwise 0. Long: bar 0 is H, bars 1 .. m are ALL C
// (every bar between the two H's must be C -- Brian 2026-11-05), m >= minC,
// and bar m + 1 is H. Short: the same with L. The first non-C bar ends the
// scan; maxSpan bounds it. No Break: the done flag stops the work.
cls0 = 0;
nC = 0;
done = false;
seqOk = false;
for (int jj = 0; jj <= (int)maxSpan; ++jj) {
    if (!done) {
        hh = high[jj + 1];
        ll = low[jj + 1];
        for (int ii = 2; ii <= (int)lookback; ++ii) {
            if (el_gt(high[jj + ii], hh)) hh = high[jj + ii];
            if (el_lt(low[jj + ii], ll)) ll = low[jj + ii];
        }
        cls = 0;
        if (el_gt(close[jj], hh)) cls = 1;
        else if (el_lt(close[jj], ll)) cls = -1;
        else if (el_gt(high[jj], hh) || el_lt(low[jj], ll)) cls = 2;
        if (jj == 0) {
            cls0 = cls;
            if (cls != 1 && cls != -1) done = true;
        } else if (cls == 2) {
            nC = nC + 1;
        } else {
            done = true;
            seqOk = (cls == cls0) && el_ge((double)nC, minC);
        }
    }
}
